// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }

    function testFuzz_property(address from, uint256 id, bytes calldata data) public {
        bytes4 expected = bytes4(keccak256("onERC721Received(address,address,uint256,bytes)"));
        bytes4 returned;
        bool ok;
        try c.onERC721Received(from, address(0), id, data) returns (bytes4 result) {
            returned = result;
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok && returned == expected);
    }
}
